ah7(a,b){return"\u0414\u043e\u0433\u043e\u0432\u043e\u0440 \u0430\u0440\u0435\u043d\u0434\u044b \u0437\u0430\u043a\u043e\u043d\u0447\u0438\u043b\u0441\u044f: "+a+", "+b+". \u0414\u0435\u043d\u044c\u0433\u0438 \u043f\u043e\u0441\u0442\u0443\u043f\u0438\u043b\u0438 \u043d\u0430 \u0441\u0447\u0451\u0442"},
gbh9(){return"\u0422\u043e\u0440\u0433 \u0443 \u043a\u0430\u043f\u043e\u0442\u0430"},
bha(a,b){return"\u0431\u044b\u043b\u043e "+a+" \xb7 \u0441\u043a\u0438\u043d\u0443\u043b\u0438 "+b},
gbh4(){return"\u0422\u0435\u0440\u043f\u0435\u043d\u0438\u0435 \u043f\u0440\u043e\u0434\u0430\u0432\u0446\u0430"},
gbgV(){return"\u0411\u043e\u043b\u044c\u0448\u0435 \u043e\u043d \u043d\u0435 \u0443\u0441\u0442\u0443\u043f\u0438\u0442. \u0420\u0435\u0448\u0430\u0439\u0442\u0435: \u0431\u0435\u0440\u0451\u0442\u0435 \u0438\u043b\u0438 \u0443\u0445\u043e\u0434\u0438\u0442\u0435."},
gbgJ(){return"\u0423\u0439\u0442\u0438"},
gbh7(){return"\u041f\u043e\u0434\u0443\u043c\u0430\u0442\u044c"},
bgA(a){return"\u041a\u0443\u043f\u0438\u0442\u044c \u0437\u0430 "+a},
bh6(a){return"\xab"+a+"\xbb"},
bgC(a){return"\u0412\u0441\u0442\u0440\u0435\u0447\u043d\u043e\u0435: \u2212"+a},
gbgM(){return"\u041d\u0435\u0442"},
gbgv(){return"\u0421\u043e\u0433\u043b\u0430\u0441\u0435\u043d"},
gbgN(){return"\u0410\u0440\u0433\u0443\u043c\u0435\u043d\u0442\u044b \u043a\u043e\u043d\u0447\u0438\u043b\u0438\u0441\u044c."},
gbh5(){return"\u0412\u044b\u0431\u0435\u0440\u0438\u0442\u0435 \u0434\u043e\u0432\u043e\u0434:"},
gbgx(){return"\u0414\u043e\u0432\u043e\u0434:"},
gbgy(){return"\u041f\u043e\u043b\u043e\u043c\u043a\u0438, \u0437\u0430\u043c\u0435\u0440\u044b, \u043d\u0430\u043b\u0438\u0447\u043d\u044b\u0435 \u2014 \u043a\u0430\u0436\u0434\u044b\u0439 \u0434\u043e\u0432\u043e\u0434 \u043c\u043e\u0436\u043d\u043e \u043f\u0440\u0435\u0434\u044a\u044f\u0432\u0438\u0442\u044c \u043e\u0434\u0438\u043d \u0440\u0430\u0437"},
gbgZ(){return"\u0426\u0435\u043d\u0443 \u0441\u0431\u0438\u0432\u0430\u0442\u044c \u0443\u0436\u0435 \u043d\u0435\u043a\u0443\u0434\u0430"},
gbgL(){return"\u0421\u043a\u0440\u043e\u043c\u043d\u043e"},
gbgG(){return"\u041e\u0431\u043e\u0441\u043d\u043e\u0432\u0430\u043d\u043d\u043e"},
gbgK(){return"\u041f\u043e \u043c\u0430\u043a\u0441\u0438\u043c\u0443\u043c\u0443"},
gbgz(){return"\u041f\u043e\u043f\u0440\u043e\u0441\u0438\u0442\u044c"},
gbgH(){return"\u0421\u043a\u043e\u043b\u044c\u043a\u043e \u043f\u043e\u043f\u0440\u043e\u0441\u0438\u0442\u044c?"},
gbgI(){return"\u0427\u0435\u043c \u0431\u043e\u043b\u044c\u0448\u0435 \u043f\u0440\u043e\u0441\u0438\u0442\u0435 \u2014 \u0442\u0435\u043c \u043c\u0435\u043d\u044c\u0448\u0435 \u0448\u0430\u043d\u0441 \u0438 \u0442\u0435\u0440\u043f\u0435\u043d\u0438\u0435 \u043f\u0440\u043e\u0434\u0430\u0432\u0446\u0430"},
bgB(a){return"\u0448\u0430\u043d\u0441 "+a+"%"},
